<template>
 <div class="activity-backdrop" @click.self="$emit('close')"><section class="activity-dialog" role="dialog" aria-modal="true" aria-labelledby="activity-title" @keydown.esc="$emit('close')">
  <header><div><h2 id="activity-title">{{ tr('Actividad de','Activity for') }} {{ user.name }}</h2><p>{{ tr('Cambios registrados por el sistema. Las páginas visitadas y los intentos fallidos no se incluyen.','Changes recorded by the system. Page views and failed attempts are not included.') }}</p></div><button type="button" class="btn btn-outline-secondary" @click="$emit('close')">{{ tr('Cerrar','Close') }}</button></header>
  <p v-if="!superadmin" class="scope-note">{{ tr('Solo se muestran registros asociados de forma verificable a esta iglesia; la actividad anterior puede estar incompleta.','Only records verifiably associated with this church are shown; older activity may be incomplete.') }}</p>
  <form class="filters" @submit.prevent="load(1)"><label>{{ tr('Desde','From') }}<input v-model="filters.from" type="date" class="form-control" /></label><label>{{ tr('Hasta','To') }}<input v-model="filters.to" type="date" :min="filters.from||undefined" class="form-control" /></label><label>{{ tr('Módulo','Module') }}<select v-model="filters.module" class="form-select"><option value="">{{ tr('Todos','All') }}</option><option v-for="(text,key) in modules" :key="key" :value="key">{{ text }}</option></select></label><button class="btn btn-primary" :disabled="loading">{{ tr('Consultar','Search') }}</button></form>
  <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="loading" role="status">{{ tr('Cargando…','Loading…') }}</p><p v-else-if="!entries.length">{{ tr('No hay actividad registrada para este período.','No recorded activity for this period.') }}</p>
  <ol v-else class="timeline"><li v-for="entry in entries" :key="entry.id"><span class="timeline-dot" aria-hidden="true"></span><div><strong>{{ actionLabel(entry.action) }} · {{ modules[entry.module] }}</strong><span v-if="entry.item_id"> · #{{ entry.item_id }}</span><time :datetime="entry.at">{{ formatDate(entry.at) }}</time></div></li></ol>
  <nav v-if="lastPage>1" class="pager" :aria-label="tr('Páginas de actividad','Activity pages')"><button class="btn btn-outline-secondary" :disabled="loading||page<=1" @click="load(page-1)">{{ tr('Anterior','Previous') }}</button><span>{{ page }} / {{ lastPage }}</span><button class="btn btn-outline-secondary" :disabled="loading||page>=lastPage" @click="load(page+1)">{{ tr('Siguiente','Next') }}</button></nav>
 </section></div>
</template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {apiClient} from '../services/authApi'
import {useUiStore} from '../stores/uiStore'
const props=defineProps({user:{type:Object,required:true},superadmin:Boolean})
defineEmits(['close'])
const ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const filters=reactive({from:'',to:'',module:''}),entries=ref([]),loading=ref(false),error=ref(''),page=ref(1),lastPage=ref(1)
const modules=computed(()=>({calendar:tr('Calendario','Calendar'),objectives:tr('Objetivos','Objectives'),meetings:tr('Juntas','Meetings'),meeting_points:tr('Puntos de junta','Meeting points'),members:tr('Miembros','Members'),visitors:tr('Visitas','Visitors'),attendance:tr('Asistencia','Attendance'),budget:tr('Presupuesto','Budget'),inventory:tr('Inventario','Inventory'),committees:tr('Comités','Committees'),departments:tr('Departamentos','Departments'),users:tr('Usuarios','Users'),account:tr('Cuenta','Account'),other:tr('Otra actividad','Other activity')}))
const actionLabel=action=>({create:tr('Acción registrada','Action recorded'),update:tr('Actualización','Update'),delete:tr('Eliminación','Deletion'),login:tr('Inicio de sesión','Sign-in'),logout:tr('Cierre de sesión','Sign-out'),register:tr('Registro','Registration'),password_reset:tr('Solicitud de recuperación','Recovery request'),other:tr('Acción registrada','Action recorded')})[action]||tr('Acción registrada','Action recorded')
const formatDate=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString(ui.locale==='es'?'es':'en')}
async function load(next){loading.value=true;error.value='';try{const prefix=props.superadmin?'superadmin':'secretary';const {data}=await apiClient.get(`/${prefix}/users/${props.user.id}/activity`,{params:{...filters,page:next}});entries.value=data.data;page.value=data.current_page;lastPage.value=data.last_page}catch{error.value=tr('No se pudo cargar la actividad.','Unable to load activity.')}finally{loading.value=false}}
onMounted(()=>load(1))
</script>
<style scoped>
.activity-backdrop{position:fixed;inset:0;z-index:3000;background:#10271db3;display:grid;place-items:center;padding:16px}.activity-dialog{width:min(760px,100%);max-height:90dvh;overflow:auto;border-radius:14px;background:#fff;color:#243d32;padding:24px;box-shadow:0 16px 60px #0004}.activity-dialog header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.activity-dialog h2{font-size:20px}.activity-dialog p,.scope-note{font-size:13px;color:#53695b}.activity-dialog .btn{width:auto}.scope-note{padding:10px;background:#eef5f1;border-radius:8px}.filters{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin:16px 0}.filters label{display:grid;gap:5px;flex:1 1 130px;font-size:12px}.filters .btn-primary{background:#1f6f5c;border-color:#1f6f5c}.timeline{list-style:none;padding:0;margin:15px 0}.timeline li{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid #e6eee8}.timeline-dot{width:10px;height:10px;margin-top:5px;border-radius:50%;background:#368668;flex:none}.timeline time{display:block;color:#66796c;font-size:12px;margin-top:4px}.pager{display:flex;justify-content:center;align-items:center;gap:12px;margin-top:16px}@media(max-width:600px){.activity-dialog{padding:16px}.filters label{flex-basis:100%}}
</style>
